"""A double-entry journal: the amounts of every transaction add up to zero."""

from __future__ import annotations

from collections import defaultdict
from dataclasses import dataclass


@dataclass(frozen=True)
class Transaction:
    """A dated, described set of (account, amount in cents) entries."""

    date: str
    memo: str
    entries: tuple[tuple[str, int], ...]


class Journal:
    """Posted transactions in order, and the account balances they add up to."""

    def __init__(self) -> None:
        self.transactions: list[Transaction] = []

    def post(self, date: str, memo: str, entries: list[tuple[str, int]]) -> Transaction:
        """Record a transaction; raises ValueError unless its amounts sum to zero."""
        total = sum(amount for _, amount in entries)
        if total != 0:
            raise ValueError(f"transaction {memo!r} does not balance (off by {total})")
        transaction = Transaction(date, memo, tuple(entries))
        self.transactions.append(transaction)
        return transaction

    def split(self, date: str, memo: str, total_cents: int, accounts: list[str]) -> Transaction:
        """Pay total_cents from the bank, shared evenly across accounts; leftover cents go first."""
        share, leftover = divmod(total_cents, len(accounts))
        entries = [(acct, share + (1 if i < leftover else 0)) for i, acct in enumerate(accounts)]
        return self.post(date, memo, entries + [("assets:bank", -total_cents)])

    def open_account(self, date: str, account: str, cents: int) -> Transaction:
        """Record an existing balance, balanced against equity:opening-balances."""
        entries = [(account, cents), ("equity:opening-balances", -cents)]
        return self.post(date, f"opening balance of {account}", entries)

    def balances(self) -> dict[str, int]:
        """The balance of every account in cents, sorted by account name."""
        totals: dict[str, int] = defaultdict(int)
        for transaction in self.transactions:
            for account, amount in transaction.entries:
                totals[account] += amount
        return dict(sorted(totals.items()))

    def accounts(self) -> list[str]:
        """Sorted names of every account used in the journal."""
        return sorted({account for t in self.transactions for account, _ in t.entries})

