import pytest

from bookkeep.importer import import_rows, to_cents
from bookkeep.journal import Journal
from bookkeep.report import format_cents, trial_balance


def test_post_and_balances():
    journal = Journal()
    journal.post("2026-03-01", "rent", [("expenses:rent", 120000), ("assets:bank", -120000)])
    assert journal.balances() == {"assets:bank": -120000, "expenses:rent": 120000}


def test_unbalanced_transaction_is_rejected():
    with pytest.raises(ValueError):
        Journal().post("2026-03-01", "typo", [("expenses:rent", 120000), ("assets:bank", -12000)])


def test_to_cents():
    assert to_cents("-25.10") == -2510
    assert to_cents("40") == 4000


def test_import_categorized_row():
    journal = Journal()
    row = {"date": "2026-03-05", "memo": "grocer", "amount": "-25.10", "category": "expenses:food"}
    assert import_rows(journal, [row]) == 1
    assert journal.balances() == {"assets:bank": -2510, "expenses:food": 2510}


def test_format_cents():
    assert format_cents(1234) == "12.34"
    assert format_cents(-5) == "-0.05"


def test_trial_balance_total_is_zero():
    journal = Journal()
    journal.post("2026-03-01", "rent", [("expenses:rent", 120000), ("assets:bank", -120000)])
    assert trial_balance(journal).splitlines()[-1].split() == ["total", "0.00"]

